typedef long long ll;

typedef struct {
    ll d;
    int id;
} Node;

typedef struct {
    int child;
    int parent;
} EdgeAns;

int cmp_node(const void *a, const void *b) {
    const Node *x = (const Node *)a;
    const Node *y = (const Node *)b;
    if (x->d < y->d) return -1;
    if (x->d > y->d) return 1;
    return 0;
}

int lower_bound_nodes(Node *arr, int n, ll val) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m].d < val) l = m + 1;
        else r = m;
    }
    return l;
}

