        Queue<Integer> q = new LinkedList<>();
        dist[1]=0; q.add(1);
        while(!q.isEmpty()){int v=q.poll();for(int u:adj.get(v)) if(dist[u]<0){dist[u]=dist[v]+1;q.add(u);}}
        long s=0; for(int i=1;i<=N;i++) s+=dist[i];
        calc[1]=s;
        // reroot
        int[] sz2 = new int[N+1];
        // compute subtree sizes rooted at 1
        int[] par2 = new int[N+1]; Arrays.fill(par2,-1);
        int[] order = new int[N]; int oi=0;
        int[] bfsQ = new int[N]; int head=0,tail=0;
        bfsQ[tail++]=1; par2[1]=0;
        while(head<tail){int v=bfsQ[head++];order[oi++]=v;for(int u:adj.get(v)) if(par2[u]<0&&u!=1){par2[u]=v;bfsQ[tail++]=u;}}
        for(int i=0;i<N;i++) sz2[order[i]]=1;
        for(int i=N-1;i>=1;i--){int v=order[i];sz2[par2[v]]+=sz2[v];}
        for(int i=1;i<N;i++){int v=order[i];calc[v]=calc[par2[v]]-(sz2[v])+(N-sz2[v]);}
        for(int i=1;i<=N;i++) if(calc[i]!=D[i]){ok=false;break;}
        if(!ok){System.out.println("No");return;}
        System.out.println("Yes");
        StringBuilder sb=new StringBuilder();
        for(int[] e:edgeList) sb.append(e[0]).append(" ").append(e[1]).append("\n");
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Node {
        long d;
        int id;
        Node(long d, int id) {
            this.d = d;
            this.id = id;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] D = new long[N + 1];
        Node[] arr = new Node[N];
        HashMap<Long, Integer> map = new HashMap<>(N * 2);

        for (int i = 1; i <= N; i++) {
            D[i] = fs.nextLong();
            arr[i - 1] = new Node(D[i], i);
            map.put(D[i], i); // all distinct
        }

        Arrays.sort(arr, Comparator.comparingLong(a -> a.d));

        long[] size = new long[N + 1];
        Arrays.fill(size, 1);

        int[] eu = new int[N - 1];
        int[] ev = new int[N - 1];
        int eidx = 0;

        // Process from largest D to smallest D
        for (int idx = N - 1; idx >= 1; idx--) {
            int v = arr[idx].id;
            long s = size[v];
            long parentD = D[v] - N + 2L * s;

            Integer pObj = map.get(parentD);
            if (pObj == null) {
                System.out.println(-1);
                return;
            }
            int p = pObj;
            if (D[p] >= D[v]) { // parent must have smaller D
                System.out.println(-1);
                return;
            }

            eu[eidx] = v;
            ev[eidx] = p;
            eidx++;

            size[p] += size[v];
        }

        int root = arr[0].id;

        // Verify by subtree sizes:
        // For the true root, sum of depths to all vertices must equal D[root].
        long depthSum = 0;
        ArrayDeque<int[]> dq = new ArrayDeque<>();
        dq.add(new int[]{root, 0, 0}); // node, parent, depth

        List<Integer>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < eidx; i++) {
            g[eu[i]].add(ev[i]);
            g[ev[i]].add(eu[i]);
        }

        boolean[] vis = new boolean[N + 1];
        vis[root] = true;
        int visited = 0;
        while (!dq.isEmpty()) {
            int[] cur = dq.poll();
            int v = cur[0], par = cur[1], dep = cur[2];
            visited++;
            depthSum += dep;
            for (int to : g[v]) {
                if (to == par) continue;
                dq.add(new int[]{to, v, dep + 1});
            }
        }

        if (visited != N || depthSum != D[root]) {
            System.out.println(-1);
            return;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < eidx; i++) {
            sb.append(eu[i]).append(' ').append(ev[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}
